        slot = datetime.datetime(d.year, d.month, d.day, hh, mm)
        if d in allowed and 600 <= hh * 60 + mm <= 1080 and slot > now:
            ok = True
            vars['cb_date'] = d.isoformat()
            vars['cb_hhmm'] = '%02d:%02d' % (hh, mm)
except Exception:
    ok = False
if ok:
    vars['cb_state'] = 'book'
else:
    tries = tries + 1
    vars['cb_state'] = 'retry' if tries < 2 else 'give_up'
