import datetime
import json

HOL = ['2026-10-26', '2026-11-11', '2026-11-26', '2026-12-25', '2027-01-01']
GUN = ['Pazartesi', 'Salı', 'Çarşamba', 'Perşembe', 'Cuma', 'Cumartesi', 'Pazar']
AY = ['Ocak', 'Şubat', 'Mart', 'Nisan', 'Mayıs', 'Haziran', 'Temmuz', 'Ağustos', 'Eylül', 'Ekim', 'Kasım', 'Aralık']

def parse_now(value):
    s = str(value or '').strip().replace(' ', 'T').rstrip('Z')
    for fmt, size in (('%Y-%m-%dT%H:%M:%S', 19), ('%Y-%m-%dT%H:%M', 16), ('%Y-%m-%d', 10)):
        try:
            return datetime.datetime.strptime(s[:size], fmt)
        except ValueError:
            pass
    raise ValueError('now')

def is_bd(d, hol):
    return d.weekday() < 5 and d not in hol

def next_bd(d, hol):
    d = d + datetime.timedelta(days=1)
    while not is_bd(d, hol):
        d = d + datetime.timedelta(days=1)
    return d

def add_bd(d, n, hol):
    for _ in range(int(n)):
        d = next_bd(d, hol)
    return d

def last_bd_week(monday, hol):
    for k in (4, 3, 2, 1, 0):
        d = monday + datetime.timedelta(days=k)
        if is_bd(d, hol):
            return d
    return None

def spoken(d):
    return str(d.day) + ' ' + AY[d.month - 1] + ' ' + str(d.year) + ' ' + GUN[d.weekday()]

def money(v):
    v = round(float(v), 2)
    if v == int(v):
        s = '{:,.0f}'.format(v).replace(',', '.')
    else:
        s = '{:,.2f}'.format(v).replace(',', 'X').replace('.', ',').replace('X', '.')
    return s + ' lira'

def as_list(value):
    if isinstance(value, list):
        return value
    if isinstance(value, str):
        try:
            value = json.loads(value)
        except ValueError:
            return []
    if isinstance(value, dict):
        return [value]
    return value if isinstance(value, list) else []

def list_from_vars(vars, name, prefixes):
    found = as_list(vars.get(name)) if vars.get(name) not in (None, '') else []
    if found:
        return found
    for prefix in prefixes:
        rows = dict()
        start = prefix + '.'
        for key, value in vars.items():
            if not str(key).startswith(start):
                continue
            rest = str(key)[len(start):]
            idx, _, field = rest.partition('.')
            if idx.isdigit() and field:
                rows.setdefault(int(idx), dict())[field] = value
        if rows:
            return [rows[i] for i in sorted(rows)]
        whole = vars.get(prefix)
        if whole not in (None, ''):
            got = as_list(whole)
            if got:
                return got
    return []

try:
    now = parse_now(vars.get('now'))
    today = now.date()
    hol = set(datetime.date.fromisoformat(h) for h in HOL)
    items = list_from_vars(vars, 'products', ['load_account_response.data.products', 'get_account_response.data.products'])
    p = items[0]
    typ = str(p.get('type') or '')
    days = int(float(p.get('days_late') or 0))
    full = float(p.get('past_due') or 0)
    if typ == 'credit_card':
        floor = float(p.get('minimum_payment') or 0)
        last4 = str(p.get('card_last4') or '')
        label = last4 + ' ile biten kredi kartı'
        poss = last4 + ' ile biten kredi kartınızda'
    else:
        floor = float(p.get('instalment_amount') or 0)
        label = 'taşıt kredisi' if typ == 'car_loan' else 'ihtiyaç kredisi'
        poss = 'taşıt kredinizde' if typ == 'car_loan' else 'ihtiyaç kredinizde'
    if days <= 7:
        n, att = 12, 1
    else:
        n, att = 7, 2
    deadline = add_bd(today, n, hol)
    monday = today - datetime.timedelta(days=today.weekday())
    a1 = last_bd_week(monday, hol)
    if a1 is None or a1 <= today:
        a1 = last_bd_week(monday + datetime.timedelta(days=7), hol)
    if a1 is None or a1 > deadline:
        a1 = deadline
    table = []
    for k in range(0, 22):
        d = today + datetime.timedelta(days=k)
        table.append(d.isoformat() + ' ' + GUN[d.weekday()] + (' iş günü' if is_bd(d, hol) else ' iş günü değil'))
    vars['facts_text'] = ('Bugün ' + spoken(today) + '. Ürün: ' + label + '. Vadesi geçmiş tutar: ' + money(full) + '. Gecikme: ' + str(days) +
                          ' gün. Taban tutar: ' + money(floor) + '. Son tarih: ' + spoken(deadline) + '. Takvim: ' + '; '.join(table) + '.')
    vars['say_text'] = ('Doğrulama için teşekkür ederim. Gecikmiş bir ödeme nedeniyle tahsilat ekibinden arıyorum. ' + poss + ' ' + str(days) +
                        ' gündür gecikmiş ' + money(full) + 'lık vadesi geçmiş tutar var. Bu ödemeyi bugün yapabilir misiniz?')
    vars['full'] = str(full)
    vars['floor'] = str(floor)
    vars['deadline'] = deadline.isoformat()
    vars['a1'] = a1.isoformat()
    vars['attempts'] = str(att)
    vars['label'] = label
    vars['rec_product'] = str(p.get('product_id') or '')
    vars['cur_amount'] = str(full)
    vars['cur_date'] = today.isoformat()
    vars['phase'] = 'ask'
    vars['refusals'] = '0'
    vars['floor_offered'] = '0'
    vars['too_much'] = '0'
    vars['vague_asked'] = '0'
    vars['stop_count'] = '0'
    vars['reply'] = 'stay'
    vars['close_outcome'] = 'no_promise'
    vars['close_reason'] = 'refused'
    vars['facts_state'] = 'ok'
except Exception:
    vars['facts_text'] = ''
    vars['say_text'] = ''
    vars['facts_state'] = 'error'

