import datetime
import re

HOL = ['2026-10-26', '2026-11-11', '2026-11-26', '2026-12-25', '2027-01-01']
GUN = ['Pazartesi', 'Salı', 'Çarşamba', 'Perşembe', 'Cuma', 'Cumartesi', 'Pazar']
AY = ['Ocak', 'Şubat', 'Mart', 'Nisan', 'Mayıs', 'Haziran', 'Temmuz', 'Ağustos', 'Eylül', 'Ekim', 'Kasım', 'Aralık']
NUMS = [('bir', 1), ('iki', 2), ('üç', 3), ('dört', 4), ('beş', 5), ('altı', 6), ('yedi', 7), ('sekiz', 8), ('dokuz', 9)]
TENS = [('otuz', 30), ('yirmi', 20), ('on', 10)]
REST = ' Kalan tutar vadesi geçmiş olarak kalır.'

def parse_now(value):
    s = str(value or '').strip().replace(' ', 'T').rstrip('Z')
    for fmt, size in (('%Y-%m-%dT%H:%M:%S', 19), ('%Y-%m-%dT%H:%M', 16), ('%Y-%m-%d', 10)):
        try:
            return datetime.datetime.strptime(s[:size], fmt)
        except ValueError:
            pass
    raise ValueError('now')

def is_bd(d, hol):
    return d.weekday() < 5 and d not in hol

def next_bd(d, hol):
    d = d + datetime.timedelta(days=1)
    while not is_bd(d, hol):
        d = d + datetime.timedelta(days=1)
    return d

def spoken(d):
    return str(d.day) + ' ' + AY[d.month - 1] + ' ' + str(d.year) + ' ' + GUN[d.weekday()]

def money(v):
    v = round(float(v), 2)
    if v == int(v):
        s = '{:,.0f}'.format(v).replace(',', '.')
    else:
        s = '{:,.2f}'.format(v).replace(',', 'X').replace('.', ',').replace('X', '.')
    return s + ' lira'

def tr_lower(s):
    return str(s or '').replace('İ', 'i').replace('I', 'ı').lower()

def num_words(s):
    for tw, tv in TENS:
        for uw, uv in NUMS:
            s = re.sub(r'\b' + tw + r'\s*' + uw + r'\b', str(tv + uv), s)
    for tw, tv in TENS:
        s = re.sub(r'\b' + tw + r'\b', str(tv), s)
    for uw, uv in NUMS:
        s = re.sub(r'\b' + uw + r'\b', str(uv), s)
    return s

def resolve(text, today):
    s = num_words(tr_lower(text).strip())
    if not s:
        return None
    m = re.search(r'(\d{4})-(\d{1,2})-(\d{1,2})', s)
    if m:
        return datetime.date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
    m = re.search(r'\b(\d{1,2})[./](\d{1,2})(?:[./](\d{2,4}))?\b', s)
    if m:
        y = int(m.group(3)) if m.group(3) else today.year
        y = y + 2000 if y < 100 else y
        d = datetime.date(y, int(m.group(2)), int(m.group(1)))
        if not m.group(3) and d < today:
            d = datetime.date(y + 1, d.month, d.day)
        return d
    for i, a in enumerate(AY):
        m = re.search(r'\b(\d{1,2})\s*' + tr_lower(a)[:3], s)
        if m:
            d = datetime.date(today.year, i + 1, int(m.group(1)))
            if d < today:
                d = datetime.date(today.year + 1, i + 1, int(m.group(1)))
            return d
    if 'öbür gün' in s or 'ertesi gün' in s:
        return today + datetime.timedelta(days=2)
    if 'yarın' in s:
        return today + datetime.timedelta(days=1)
    if 'bugün' in s:
        return today
    monday = today - datetime.timedelta(days=today.weekday())
    for i in sorted(range(7), key=lambda k: -len(GUN[k])):
        if re.search(r'\b' + tr_lower(GUN[i]), s):
            if re.search(r'gelecek|önümüzdeki|haftaya|sonraki', s):
                return monday + datetime.timedelta(days=7 + i)
            if re.search(r'\bbu\b', s):
                return monday + datetime.timedelta(days=i)
            d = monday + datetime.timedelta(days=i)
            return d if d >= today else d + datetime.timedelta(days=7)
    m = re.search(r'ayın\s*(\d{1,2})', s)
    if m:
        return datetime.date(today.year, today.month, int(m.group(1)))
    return None

try:
    now = parse_now(vars.get('now'))
    today = now.date()
    hol = set(datetime.date.fromisoformat(h) for h in HOL)
    full = float(vars.get('full') or 0)
    floor = float(vars.get('floor') or 0)
    deadline = datetime.date.fromisoformat(str(vars.get('deadline')))
    a1 = datetime.date.fromisoformat(str(vars.get('a1')))
    attempts = int(vars.get('attempts') or 1)
    label = str(vars.get('label') or '')
    st = dict(refusals=int(vars.get('refusals') or 0), floor_offered=vars.get('floor_offered') == '1',
              too_much=vars.get('too_much') == '1', vague_asked=vars.get('vague_asked') == '1',
              stops=int(vars.get('stop_count') or 0), amount=float(vars.get('cur_amount') or full),
              date=str(vars.get('cur_date') or today.isoformat()), phase=str(vars.get('phase') or 'ask'))
    out = dict(say='', state='talk')
    reply = str(vars.get('reply') or 'stay')
    own_date = str(vars.get('own_date') or '').strip()
    own_amount = str(vars.get('own_amount') or '').strip()
    if reply == 'stay' and (own_date or own_amount):
        reply = 'own'

    def refuse(prefix):
        if vars.get('hardship') == '1':
            out['state'] = 'hardship_end'
            return
        st['refusals'] += 1
        st['phase'] = 'ask'
        r = st['refusals']
        if r == 1:
            amt = floor if st['too_much'] else full
            st['amount'] = amt
            st['date'] = a1.isoformat()
            out['say'] = prefix + 'O zaman ' + spoken(a1) + ' günü ' + money(amt) + ' ödeyebilir misiniz?' + (REST if amt < full else '')
        elif r == 2 and attempts >= 2:
            st['amount'] = floor
            st['date'] = deadline.isoformat()
            out['say'] = prefix + 'Son tarihiniz ' + spoken(deadline) + '. Bu tarihte yalnızca taban tutar olan ' + money(floor) + ' ödeyebilir misiniz?' + REST
        else:
            out['state'] = 'refused'

    def check(amt, d):
        amt = min(amt, full)
        if d < today:
            out['say'] = 'Söz tarihi bugün veya daha sonraki bir gün olmalı. Hangi gün ödeyebilirsiniz?'
        elif d > deadline:
            st['amount'] = amt
            st['date'] = deadline.isoformat()
            st['phase'] = 'ask'
            out['say'] = 'Kaydedebileceğim en geç tarih son tarihiniz olan ' + spoken(deadline) + '. Bu tarihte ' + money(amt) + ' ödeyebilir misiniz?'
        elif not is_bd(d, hol):
            nb = next_bd(d, hol)
            st['amount'] = amt
            st['date'] = nb.isoformat()
            st['phase'] = 'ask'
            out['say'] = 'Bu gün bir iş günü değil. Bir sonraki iş günü olan ' + spoken(nb) + ' tarihinde ' + money(amt) + ' ödeyebilir misiniz?'
        elif amt < floor:
            if st['floor_offered']:
                refuse('Bu tutarı kaydedemiyorum. ')
            else:
                st['floor_offered'] = True
                st['amount'] = floor
                st['date'] = d.isoformat()
                st['phase'] = 'ask'
                out['say'] = 'Bu tutar kaydedilemez. ' + spoken(d) + ' tarihinde taban tutar olan ' + money(floor) + ' ödeyebilir misiniz?' + REST
        else:
            st['amount'] = amt
            st['date'] = d.isoformat()
            st['phase'] = 'confirm'
            out['say'] = 'Özetliyorum: ' + label + ' için ' + spoken(d) + ' tarihinde ' + money(amt) + ' ödeme sözü kaydedeceğim. Onaylıyor musunuz?'

    if reply == 'yes':
        if st['phase'] == 'confirm':
            out['state'] = 'record'
        else:
            check(st['amount'], datetime.date.fromisoformat(st['date']))
    elif reply == 'own':
